+1|// Stock bubble chart + data table using D3.js v6.
+2|// Data: data/stock-descriptions.csv (50 stocks across 5 sectors; ETFs have no marketCap).
+3|
+4|(function () {
+5|    'use strict';
+6|
+7|    const CHART_WIDTH = 760;
+8|    const CHART_HEIGHT = 620;
+9|    const CHART_MARGIN = { top: 20, right: 20, bottom: 20, left: 20 };
+10|
+11|    // Deterministic sector order (sorted alphabetically for stable color mapping).
+12|    const SECTOR_ORDER = ['Energy', 'ETF', 'Financial', 'Industry', 'Information Technology'];
+13|
+14|    // Pick a palette with 5 distinct, pleasant colors.
+15|    const SECTOR_COLORS = {
+16|        'Information Technology': '#4e79a7',
+17|        'Industry':               '#f28e2b',
+18|        'Energy':                 '#e15759',
+19|        'Financial':              '#59a14f',
+20|        'ETF':                    '#9c6ade'
+21|    };
+22|
+23|    // Radius bounds for stocks with marketCap. ETFs use a fixed radius.
+24|    const MIN_RADIUS = 14;
+25|    const MAX_RADIUS = 52;
+26|    const ETF_RADIUS = 26;
+27|
+28|    // Format a market-cap number as "1.64T", "193.22B", "250.00M".
+29|    function formatMarketCap(v) {
+30|        if (v == null || Number.isNaN(v) || v === 0) return null;
+31|        const abs = Math.abs(v);
+32|        if (abs >= 1e12) return (v / 1e12).toFixed(2) + 'T';
+33|        if (abs >= 1e9)  return (v / 1e9).toFixed(2) + 'B';
+34|        if (abs >= 1e6)  return (v / 1e6).toFixed(2) + 'M';
+35|        return v.toLocaleString();
+36|    }
+37|
+38|    // Compute 5 cluster centers in a centered pentagon (plus center offset).
+39|    function clusterCenters(sectors, cx, cy, radius) {
+40|        const centers = {};
+41|        const n = sectors.length;
+42|        sectors.forEach((s, i) => {
+43|            // Start at top (-90°) and go clockwise.
+44|            const angle = (-Math.PI / 2) + (i * 2 * Math.PI / n);
+45|            centers[s] = {
+46|                x: cx + radius * Math.cos(angle),
+47|                y: cy + radius * Math.sin(angle)
+48|            };
+49|        });
+50|        return centers;
+51|    }
+52|
+53|    d3.csv('data/stock-descriptions.csv').then((rows) => {
+54|        // Parse rows into node objects.
+55|        const nodes = rows.map((r, i) => {
+56|            const mc = r.marketCap && r.marketCap !== '' ? +r.marketCap : null;
+57|            return {
+58|                index: i,
+59|                ticker: r.ticker,
+60|                name: r['full name'],
+61|                sector: r.sector,
+62|                marketCap: mc,
+63|                country: r.country || '',
+64|                website: r.website || '',
+65|                isETF: r.sector === 'ETF'
+66|            };
+67|        });
+68|
+69|        // Sort nodes deterministically for stable table + initial layout.
+70|        nodes.sort((a, b) => {
+71|            const sa = SECTOR_ORDER.indexOf(a.sector);
+72|            const sb = SECTOR_ORDER.indexOf(b.sector);
+73|            if (sa !== sb) return sa - sb;
+74|            // Within sector, bigger market cap first; ETFs sort by ticker.
+75|            if (a.isETF && b.isETF) return d3.ascending(a.ticker, b.ticker);
+76|            return d3.descending(a.marketCap || 0, b.marketCap || 0);
+77|        });
+78|
+79|        // Radius scale: use sqrt so area is roughly proportional to market cap.
+80|        const stockCaps = nodes.filter(d => !d.isETF && d.marketCap).map(d => d.marketCap);
+81|        const radiusScale = d3.scaleSqrt()
+82|            .domain([d3.min(stockCaps), d3.max(stockCaps)])
+83|            .range([MIN_RADIUS, MAX_RADIUS]);
+84|
+85|        nodes.forEach(d => {
+86|            d.radius = d.isETF ? ETF_RADIUS : radiusScale(d.marketCap);
+87|        });
+88|
+89|        drawLegend();
+90|        drawBubbleChart(nodes);
+91|        drawTable(nodes);
+92|        wireInteractions();
+93|    });
+94|
+95|    // ---------- Legend ----------
+96|    function drawLegend() {
+97|        const legend = d3.select('#legend');
+98|        legend.selectAll('.legend-item')
+99|            .data(SECTOR_ORDER)
+100|            .enter()
+101|            .append('div')
+102|            .attr('class', 'legend-item')
+103|            .html(s => `
+104|                <span class="legend-swatch" style="background:${SECTOR_COLORS[s]}"></span>
+105|                <span>${s}</span>
+106|            `);
+107|    }
+108|
+109|    // ---------- Bubble chart ----------
+110|    function drawBubbleChart(nodes) {
+111|        const svg = d3.select('#bubble-chart')
+112|            .append('svg')
+113|            .attr('viewBox', `0 0 ${CHART_WIDTH} ${CHART_HEIGHT}`)
+114|            .attr('preserveAspectRatio', 'xMidYMid meet');
+115|
+116|        const innerW = CHART_WIDTH - CHART_MARGIN.left - CHART_MARGIN.right;
+117|        const innerH = CHART_HEIGHT - CHART_MARGIN.top - CHART_MARGIN.bottom;
+118|        const cx = CHART_MARGIN.left + innerW / 2;
+119|        const cy = CHART_MARGIN.top + innerH / 2;
+120|
+121|        // Pentagon radius chosen to keep clusters inside the chart and close together.
+122|        const centers = clusterCenters(SECTOR_ORDER, cx, cy, Math.min(innerW, innerH) * 0.26);
+123|
+124|        // Seed initial positions near each cluster center for a stable starting layout.
+125|        nodes.forEach((d, i) => {
+126|            const c = centers[d.sector];
+127|            // Deterministic offset based on index so no RNG is needed.
+128|            const theta = (i * 2.399);  // golden-angle for a nice spread
+129|            const r = 8 + (i % 5) * 3;
+130|            d.x = c.x + Math.cos(theta) * r;
+131|            d.y = c.y + Math.sin(theta) * r;
+132|        });
+133|
+134|        const g = svg.append('g').attr('class', 'bubbles');
+135|
+136|        const bubble = g.selectAll('g.bubble-group')
+137|            .data(nodes, d => d.ticker)
+138|            .enter()
+139|            .append('g')
+140|            .attr('class', 'bubble-group');
+141|
+142|        bubble.append('circle')
+143|            .attr('class', 'bubble')
+144|            .attr('data-ticker', d => d.ticker)
+145|            .attr('r', d => d.radius)
+146|            .attr('fill', d => SECTOR_COLORS[d.sector])
+147|            .attr('fill-opacity', 0.85);
+148|
+149|        bubble.append('text')
+150|            .attr('class', 'bubble-label')
+151|            .text(d => d.ticker)
+152|            .attr('font-size', d => Math.max(9, Math.min(14, d.radius * 0.45)));
+153|
+154|        // Tooltip handlers (ETFs skipped per requirements).
+155|        const tooltip = d3.select('#tooltip');
+156|        bubble
+157|            .on('mouseover', function (event, d) {
+158|                if (d.isETF) return;
+159|                tooltip
+160|                    .classed('visible', true)
+161|                    .html(`
+162|                        <div class="tt-ticker">${d.ticker}</div>
+163|                        <div class="tt-name">${d.name}</div>
+164|                        <div class="tt-sector">${d.sector}</div>
+165|                    `);
+166|            })
+167|            .on('mousemove', function (event, d) {
+168|                if (d.isETF) return;
+169|                tooltip
+170|                    .style('left', (event.pageX + 14) + 'px')
+171|                    .style('top',  (event.pageY + 14) + 'px');
+172|            })
+173|            .on('mouseout', function () {
+174|                tooltip.classed('visible', false);
+175|            })
+176|            .on('click', function (event, d) {
+177|                selectTicker(d.ticker);
+178|            });
+179|
+180|        // Force simulation: cluster by sector, prevent overlap.
+181|        const simulation = d3.forceSimulation(nodes)
+182|            .force('x', d3.forceX(d => centers[d.sector].x).strength(0.18))
+183|            .force('y', d3.forceY(d => centers[d.sector].y).strength(0.18))
+184|            .force('charge', d3.forceManyBody().strength(-12))
+185|            .force('collide', d3.forceCollide(d => d.radius + 1.5).strength(0.9))
+186|            .alpha(1)
+187|            .alphaDecay(0.035)
+188|            .on('tick', () => {
+189|                // Keep bubbles inside the chart area.
+190|                nodes.forEach(d => {
+191|                    d.x = Math.max(CHART_MARGIN.left + d.radius,
+192|                                   Math.min(CHART_WIDTH - CHART_MARGIN.right - d.radius, d.x));
+193|                    d.y = Math.max(CHART_MARGIN.top + d.radius,
+194|                                   Math.min(CHART_HEIGHT - CHART_MARGIN.bottom - d.radius, d.y));
+195|                });
+196|                bubble.attr('transform', d => `translate(${d.x},${d.y})`);
+197|            });
+198|
+199|        // Expose for interactions.
+200|        window.__viz = Object.assign(window.__viz || {}, {
+201|            svg,
+202|            bubble,
+203|            simulation,
+204|            nodes
+205|        });
+206|    }
+207|
+208|    // ---------- Data table ----------
+209|    function drawTable(nodes) {
+210|        const container = d3.select('#table-container');
+211|
+212|        const table = container.append('table').attr('class', 'stock-table');
+213|        const thead = table.append('thead').append('tr');
+214|
+215|        ['Ticker symbol', 'Full company name', 'Sector', 'Market cap'].forEach(col => {
+216|            thead.append('th').text(col);
+217|        });
+218|
+219|        const tbody = table.append('tbody');
+220|
+221|        const rows = tbody.selectAll('tr')
+222|            .data(nodes, d => d.ticker)
+223|            .enter()
+224|            .append('tr')
+225|            .attr('data-ticker', d => d.ticker)
+226|            .on('click', function (event, d) {
+227|                selectTicker(d.ticker);
+228|            });
+229|
+230|        rows.append('td').attr('class', 'ticker').text(d => d.ticker);
+231|        rows.append('td').text(d => d.name);
+232|        rows.append('td').append('span')
+233|            .attr('class', 'sector-tag')
+234|            .style('background', d => SECTOR_COLORS[d.sector])
+235|            .text(d => d.sector);
+236|        rows.append('td')
+237|            .attr('class', d => {
+238|                const f = formatMarketCap(d.marketCap);
+239|                return 'marketcap' + (f == null ? ' na' : '');
+240|            })
+241|            .text(d => {
+242|                const f = formatMarketCap(d.marketCap);
+243|                return f == null ? '—' : f;
+244|            });
+245|
+246|        window.__viz = Object.assign(window.__viz || {}, { rows });
+247|    }
+248|
+249|    // ---------- Linked selection ----------
+250|    function wireInteractions() {
+251|        // Clicking the empty chart background clears selection.
+252|        d3.select('#bubble-chart svg').on('click', function (event) {
+253|            if (event.target.tagName === 'svg') selectTicker(null);
+254|        });
+255|    }
+256|
+257|    function selectTicker(ticker) {
+258|        const v = window.__viz;
+259|        if (!v) return;
+260|
+261|        v.bubble.selectAll('circle.bubble')
+262|            .classed('selected', d => ticker != null && d.ticker === ticker);
+263|        v.rows.classed('selected', d => ticker != null && d.ticker === ticker);
+264|
+265|        if (ticker == null) return;
+266|
+267|        // Scroll the selected row into view inside the table panel.
+268|        const node = document.querySelector(`tr[data-ticker="${ticker}"]`);
+269|        if (node && typeof node.scrollIntoView === 'function') {
+270|            node.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
+271|        }
+272|    }
+273|})();
